import Model from 'flarum/common/Model';
export default class Badge extends Model {
  // Attributes
  name = (() => Model.attribute('name'))();
  slug = (() => Model.attribute('slug'))();
  description = (() => Model.attribute('description'))();
  icon = (() => Model.attribute('icon'))();
  iconColor = (() => Model.attribute('iconColor'))();
  backgroundColor = (() => Model.attribute('backgroundColor'))();
  triggerConfig = (() => Model.attribute('triggerConfig'))();
  actions = (() => Model.attribute('actions'))();
  isActive = (() => Model.attribute('isActive'))();
  isVisible = (() => Model.attribute('isVisible'))();
  earnedCount = (() => Model.attribute('earnedCount'))();
  order = (() => Model.attribute('order'))();
  createdAt = (() => Model.attribute('createdAt', Model.transformDate))();
  rarity = (() => Model.attribute('rarity'))();
  isEarned = (() => Model.attribute('isEarned'))();
  canEdit = (() => Model.attribute('canEdit'))();
  categoryId = (() => Model.attribute('categoryId'))();

  // Relationships
  category = (() => Model.hasOne('category'))();
}
flarum.reg.add('framio-profiles', 'badges/common/models/Badge', Badge);