import Model from 'flarum/common/Model';
export default class UserBadge extends Model {
  // Attributes
  grantedBy = (() => Model.attribute('grantedBy'))();
  reason = (() => Model.attribute('reason'))();
  isSeen = (() => Model.attribute('isSeen'))();
  showOnCard = (() => Model.attribute('showOnCard'))();
  isPrimary = (() => Model.attribute('isPrimary'))();
  earnedAt = (() => Model.attribute('earnedAt', Model.transformDate))();

  // Relationships
  user = (() => Model.hasOne('user'))();
  badge = (() => Model.hasOne('badge'))();
  grantedByUser = (() => Model.hasOne('grantedByUser'))();
}
flarum.reg.add('framio-profiles', 'badges/common/models/UserBadge', UserBadge);