import Model from 'flarum/common/Model';
export default class BadgeCategory extends Model {
  // Attributes
  name = (() => Model.attribute('name'))();
  slug = (() => Model.attribute('slug'))();
  description = (() => Model.attribute('description'))();
  isEnabled = (() => Model.attribute('isEnabled'))();
  order = (() => Model.attribute('order'))();
  createdAt = (() => Model.attribute('createdAt', Model.transformDate))();
  badgeCount = (() => Model.attribute('badgeCount'))();

  // Relationships
  badges = (() => Model.hasMany('badges'))();
}
flarum.reg.add('framio-profiles', 'badges/common/models/BadgeCategory', BadgeCategory);